mapper.select:
select t.* from ( select a.order_reg_no , a.item_no , kd.cmm_cd_nm as ship_kd_nm , mdl.item_mdl_nm , a.cnfm_qt from tb_demo_order_d a left outer join tb_demo_cmm_code_c kd on a.ship_kd_cd = kd.cmm_cd and 'SHIP_KD_CD' = kd.cmm_grp_cd join tb_demo_item_mdl_m mdl on a.item_mdl_cd = mdl.item_mdl_cd where 1=1
and a.maker_cd = #{makerCd}
and a.item_mdl_cd = #{itemMdlCd}
and ifnull(a.ship_divs_cd,'00') != '03'
) t where t.cnfm_qt > 0 order by t.order_reg_no /*[ship-svc] /maria/order/ship/sql-O.ShipOrderM.xml-selectOrderTrgtList OWNER:dev01, 개발자 */

select d.order_reg_no -- 주문등록번호 , ( select date_format( rd.data_inpt_dttm,'%Y-%m-%d') from tb_demo_ship_rqst_d rd where rd.item_no = d.item_no and rd.rqst_yn = 'Y' limit 1 ) as last_inpt_dt , d.item_no , ad.center_cd , t.last_org_cd , case when ad.center_cd != ifnull(t.last_org_cd, 'N') then 'Y' else 'N' end as org_change , t.item_kd_cd from tb_demo_order_d d left outer join tb_demo_item_m t on d.item_no = t.item_no left outer join tb_demo_ship_base_m g on g.item_mdl_cd = t.item_mdl_cd , tb_demo_order_assg_d ad where 1 = 1 and d.order_reg_no = #{orderRegNo} and d.order_reg_no = ad.order_reg_no and d.order_assg_no = ad.order_assg_no
and t.posn_org_cd = #{makerCd}
order by d.order_reg_sno -- 주문등록순번 /*[ship-svc] /maria/order/ship/sql-O.ShipOrderM.xml-selectOrderRqstD OWNER:dev01, 개발자 */

mapper.update:
update tb_demo_order_d
set order_stus_cd = #{orderStusCd}

where order_reg_no = #{orderRegNo}
and order_reg_sno = #{orderRegSno}

mapper.insert:
insert into tb_demo_ship_rqst_d (
	rqst_no
	, item_no
	, rqst_yn

)
select #{rqstNo}
	, d.item_no
	, 'Y'

from tb_demo_order_d d
where d.order_reg_no = #{orderRegNo}

mapper.delete:
delete from tb_demo_order_assg_d
where order_reg_no = #{orderRegNo}
and order_assg_no in

	#{assgNo}
